/*
 Problem: 3525. Find X Value of Array II
 Language: cpp
 Runtime: 306 ms (67.74%)
 Memory: 270.7 MB (90.97%)
 Tags: Array, Math, Segment Tree
*/
class Solution {
    struct Node {
        int product = 1;
        int freq[5]{};

        inline void init(int value, int mod) {
            product = value;
            freq[0] = freq[1] = freq[2] = freq[3] = freq[4] = 0;
            freq[value] = 1;
        }

        inline void merge(const Node& left, const Node& right, int mod) {
            const int leftProduct = left.product;
            const int newProduct = leftProduct * right.product % mod;

            int count[5]{};

            for (int remainder = 0; remainder < mod; ++remainder)
                count[remainder] = left.freq[remainder];

            for (int remainder = 0; remainder < mod; ++remainder)
                count[leftProduct * remainder % mod] += right.freq[remainder];

            product = newProduct;

            for (int remainder = 0; remainder < mod; ++remainder)
                freq[remainder] = count[remainder];
        }
    };

    int mod;
    int size;
    vector<Node> tree;

public:
    vector<int> resultArray(
        vector<int>& nums,
        int k,
        vector<vector<int>>& queries
    ) {
        mod = k;

        const int n = nums.size();
        size = bit_ceil((unsigned)n);

        tree.resize(size << 1);

        for (int index = 0; index < n; ++index)
            tree[size + index].init(nums[index] % mod, mod);

        for (int node = size - 1; node; --node)
            tree[node].merge(tree[node << 1], tree[node << 1 | 1], mod);

        auto update = [&](int index, int value) {
            int node = size + index;

            tree[node].init(value % mod, mod);

            for (node >>= 1; node; node >>= 1)
                tree[node].merge(
                    tree[node << 1],
                    tree[node << 1 | 1],
                    mod
                );
        };

        auto rangeQuery = [&](int left, int right) {
            Node prefix, suffix;

            for (left += size, right += size;
                 left <= right;
                 left >>= 1, right >>= 1) {

                if (left & 1)
                    prefix.merge(prefix, tree[left++], mod);

                if (!(right & 1))
                    suffix.merge(tree[right--], suffix, mod);
            }

            prefix.merge(prefix, suffix, mod);

            return prefix;
        };

        vector<int> answer;
        answer.reserve(queries.size());

        for (const auto& currentQuery : queries) {
            const int index = currentQuery[0];
            const int value = currentQuery[1];
            const int start = currentQuery[2];
            const int remainder = currentQuery[3];

            update(index, value);

            answer.push_back(
                rangeQuery(start, n - 1).freq[remainder]
            );
        }

        return answer;
    }
};
